def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    text = str(frequency).lower()
    p = 24 if 'hour' in text else (7 if 'day' in text else 1)
    nonnegative = min(y) >= 0.0
    if len(y) < p:
        level = float(statistics.median(y[-min(5, len(y)):]))
        return [max(0.0, level) if nonnegative else level] * h

    def predict(train, count, window, alpha):
        result = []
        for step in range(count):
            phase = (len(train) + step) % p
            same = train[phase::p]
            if not same:
                estimate = train[-1]
            else:
                recent = same[-1]
                sample = same if window == 0 else same[-window:]
                center = statistics.median(sample)
                estimate = alpha * recent + (1.0 - alpha) * center
                zero_sample = same[-min(5, len(same)):]
                zero_rate = sum(abs(v) <= 1e-12 for v in zero_sample) / len(zero_sample)
                if zero_rate >= 0.8:
                    estimate = 0.0
            if nonnegative:
                estimate = max(0.0, estimate)
            result.append(float(estimate))
        return result

    def smape(actual, predicted):
        terms = []
        for a, b in zip(actual, predicted):
            denominator = abs(a) + abs(b)
            if denominator > 1e-12:
                terms.append(200.0 * abs(a - b) / denominator)
        return sum(terms) / len(terms) if terms else 0.0

    candidates = [(w, a) for w in (1, 3, 5, 0) for a in (0.0, 0.25, 0.5, 0.75)]
    folds = []
    for back in (3, 2, 1):
        cut = len(y) - back * p
        if cut >= 2 * p:
            folds.append((y[:cut], y[cut:cut + p]))
    if not folds:
        return predict(y, h, 1, 0.0)
    ranked = []
    for window, alpha in candidates:
        errors = [smape(actual, predict(train, len(actual), window, alpha)) for train, actual in folds]
        ranked.append((max(errors), statistics.median(errors), sum(errors) / len(errors), window, alpha))
    _, _, _, window, alpha = min(ranked)
    return predict(y, h, window, alpha)

def forecast(history: list[float], horizon: int, frequency: str) -> list[float]:
    import math
    import statistics
    h = max(0, int(horizon))
    if h == 0:
        return []
    y = []
    for value in history:
        try:
            value = float(value)
            if math.isfinite(value):
                y.append(value)
        except (TypeError, ValueError):
            pass
    if not y:
        return [0.0] * h
    text = str(frequency).lower()
    p = 24 if 'hour' in text else (7 if 'day' in text else 1)
    nonnegative = min(y) >= 0.0
    if len(y) < 2 * p:
        return [float(y[(len(y) + k) % len(y)]) for k in range(h)]

    def phase_center(source, phase):
        same = source[phase::p]
        return float(statistics.median(same[-min(5, len(same)):])) if same else float(source[-1])

    def predict(train, count, context_size, neighbors, shrink):
        source = list(train)
        state = list(train)
        output = []
        while len(output) < count:
            block = min(p, count - len(output))
            phase = len(state) % p
            c = min(context_size, len(state))
            target = state[-c:]
            scale = statistics.median([abs(v - statistics.median(target)) for v in target]) if target else 0.0
            scale = max(scale, 0.1)
            matches = []
            first = phase
            for anchor in range(first, len(source) - block + 1, p):
                if anchor < c:
                    continue
                past = source[anchor - c:anchor]
                distance = sum(abs(a - b) for a, b in zip(past, target)) / (c * scale)
                matches.append((distance, anchor))
            matches.sort()
            selected = matches[:neighbors]
            for offset in range(block):
                target_phase = (phase + offset) % p
                baseline = phase_center(source, target_phase)
                if selected:
                    weights = [1.0 / (0.05 + distance) for distance, _ in selected]
                    analog = sum(weight * source[anchor + offset] for weight, (_, anchor) in zip(weights, selected)) / sum(weights)
                    estimate = (1.0 - shrink) * analog + shrink * baseline
                else:
                    estimate = baseline
                same = source[target_phase::p]
                recent = same[-min(6, len(same)):]
                zero_rate = sum(abs(v) <= 1e-12 for v in recent) / len(recent) if recent else 0.0
                if zero_rate >= 0.75:
                    estimate = 0.0
                if nonnegative:
                    estimate = max(0.0, estimate)
                output.append(float(estimate))
                state.append(float(estimate))
        return output

    def smape(actual, predicted):
        terms = []
        for a, b in zip(actual, predicted):
            denominator = abs(a) + abs(b)
            if denominator > 1e-12:
                terms.append(200.0 * abs(a - b) / denominator)
        return sum(terms) / len(terms) if terms else 0.0

    folds = []
    for back in (3, 2, 1):
        cut = len(y) - back * p
        if cut >= 3 * p:
            folds.append((y[:cut], y[cut:cut + p]))
    choices = [(c, k, s) for c in (3, 6, 12) for k in (1, 2, 3) for s in (0.0, 0.25, 0.5)]
    if not folds:
        return predict(y, h, 3, 2, 0.25)
    ranked = []
    for context_size, neighbors, shrink in choices:
        errors = [smape(actual, predict(train, len(actual), context_size, neighbors, shrink)) for train, actual in folds]
        ranked.append((max(errors), statistics.median(errors), sum(errors) / len(errors), context_size, neighbors, shrink))
    _, _, _, context_size, neighbors, shrink = min(ranked)
    return predict(y, h, context_size, neighbors, shrink)
